questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: [day index (0 Monday), h, m, place, longitude]. Day options take values 1 to 7. The two day diagnostics apply on every entry: on day-change entries the unchanged day and the day moved the wrong way; on same-day entries the day moved forward or back by one. No entry should repeat the worked example Across the Pacific. Source: original. */
L: [[2,7,30,"Honolulu",-158],[4,22,40,"Auckland",175],[0,3,15,"Los Angeles",-118],[5,20,20,"Suva",178],[2,10,30,"Lima",-77],[6,9,0,"Tokyo",140],[3,12,10,"Mexico City",-99],[0,21,50,"Wellington",175],[4,4,0,"Anchorage",-150],[2,8,45,"Brisbane",153]];
ix: 1+rand(10);
E: L[ix];
d0: E[1]; lon: E[5];
DN: ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
t0: 60*E[2]+E[3];
dl: lon-37;
east: is(dl>0);
t: t0+4*dl;
shift: floor(t/1440);
chg: is(shift#0);
day: mod(d0+shift,7);
tm: mod(t,1440);
sg: signum(dl);
/* diagnostics */
dirw: mod(t0-4*dl,1440); f15: mod(t0+15*dl,1440);
dy2: if chg then d0 else mod(d0+sg,7);
dy3: if chg then mod(d0-shift,7) else mod(d0-sg,7);
dyg: mod(day+3,7);
vday: day+1; v2: dy2+1; v3: dy3+1; vg: dyg+1;
opt1: makelist([j, is(j=vday), DN[j]], j, 1, 7);

feedbackvariables.text:
TT: 60*ans2+ans3;
yd: mod(TT-t0,1440);
c1: is(TT=tm and ans3<60 and ans3>=0 and ans2<24);
f1: is(mod(TT,1440)=tm);
w1: is(TT=dirw);
q1: is(TT=f15);
